		}

		/* @Override */
		protected bool validateSelection(DataType dataType, TableModel model) {
			if (!(model is RegistersTableModel rModel)) {
				return false;
			}
			RegisterRow row = rModel.getModelData().get(table.getEditingRow());
			if (row == null) {
				return false;
			}
			return dataType.getLength() == row.getRegister().getMinimumByteSize();
		}

		/* @Override */
		protected DataTypeManagerService getService(TableModel model) {
			if (!(model is RegistersTableModel rModel)) {
				return null;
			}
			return rModel.getServiceProvider().getService(typeof(DataTypeManagerService));
		}

		/* @Override */
		protected DataType resolveSelection(DataType dataType, TableModel model) {
			if (dataType == null || !(model is RegistersTableModel rModel)) {
				return null;
			}
			Trace trace = rModel.getTrace();
			using (Transaction tx = trace.openTransaction("Resolve DataType"))
{
				return trace.getDataTypeManager().resolve(dataType, null);
			}
		}
	}

